/* generated by tools/launcher/mklaunch.py: the launcher's pictures and sounds (the Ibara PS2 port's) */
#ifndef LAUNCH_LAYOUT_H
#define LAUNCH_LAYOUT_H

#define LA_BG_W 640
#define LA_BG_H 448
#define LA_ATLAS_W 512
#define LA_ATLAS_H 1024
#define LA_FONT_CW 8 /* the font's cells: 32 a row, rows 0x20, 0x40, 0x60 */
#define LA_FONT_CH 16

enum {
	LS_HEADER,
	LS_EXIT,
	LS_SIGN,
	LS_BAR,
	LS_LOGO_IB,
	LS_LATTICE,
	LS_FRAME,
	LS_LOADING,
	LS_ROSE,
	LS_FONT,
	LS_LOGO_BLK,
	LS_WHITE,
	LS_G_PLATE,
	LS_G_DESC,
	LS_G_HEAD,
	LS_G_BOX,
	LS_G_NUM,
	LS_G_HELP1,
	LS_G_HELP2,
	LS_G_OV1,
	LS_G_OV2,
	LS_G_OV3,
	LS_G_OV4,
	LS_G_KA,
	LS_G_KB,
	LS_G_KY,
	LS_G_KLR,
	LS_A_PLATE,
	LS_A_DESC,
	LS_COUNT
};
struct la_rect {
	short x, y, w, h;
};
extern const struct la_rect la_sprites[LS_COUNT];

extern const unsigned char la_title_z[], la_mode_z[], la_atlas_z[];
extern const unsigned la_title_z_size, la_mode_z_size, la_atlas_z_size;

/* the sounds: int16 at LA_SND_RATE, mono; vol = the PS2 port's (of 128) */
#define LA_SND_RATE 16000
enum {
	LSND_CURSOR,
	LSND_DECIDE,
	LSND_CANCEL,
	LSND_COIN,
	LSND_V_IBARA,
	LSND_V_KAKATTE,
	LSND_COUNT
};
struct la_sound {
	const short *pcm;
	unsigned n;
	int vol;
};
extern const struct la_sound la_sounds[LSND_COUNT];

/* test 75: ALLIMAGE.DAT's glyphs in the atlas, by code point (ASCII half-width, then JP_CHARS) */
#define LA_G_H 26
#define LA_G_SPACE 16
#define LA_GLYPHS 106
struct la_glyph {
	unsigned cp;
	short x, y, w, adv;
};
extern const struct la_glyph la_glyphs[LA_GLYPHS];

#endif
